package de.fitnesscoach.domain.fitness;

import java.time.*;import java.util.*;import de.fitnesscoach.data.repository.FitnessCoachRepository;import de.fitnesscoach.data.entity.*;

public final class FitnessIntelligenceService {private final FitnessCoachRepository repo;private final BaselineCalculator baselines;private final TrainingLoadCalculator load;private final RecoveryCalculator recovery;public FitnessIntelligenceService(FitnessCoachRepository repo){this(repo,new BaselineCalculator(),new DefaultTrainingLoadCalculator(),new RecoveryCalculator());}public FitnessIntelligenceService(FitnessCoachRepository repo,BaselineCalculator b,TrainingLoadCalculator l,RecoveryCalculator r){this.repo=repo;baselines=b;load=l;recovery=r;}
 public void refresh(LocalDate date){for(String metric:new String[]{"sleepMinutes","restingHeartRate","steps","distanceKm"})for(int window:new int[]{7,28,90}){List<DailyHealthEntity>d=new ArrayList<>();for(int i=window-1;i>=0;i--){DailyHealthEntity x=repo.getDailyHealth(date.minusDays(i));if(x!=null)d.add(x);}repo.saveBaseline(baselines.calculate(metric,window,d));}List<WorkoutEntity> all=repo.getWorkouts();for(int window:new int[]{7,28,90}){List<Double> daily=new ArrayList<>();for(int i=window-1;i>=0;i--){LocalDate day=date.minusDays(i);daily.add(load.total(workoutsForDay(all,day)));}repo.saveBaseline(baselines.calculateValues("trainingLoad",window,daily));}double l7=load.total(workoutsBetween(all,date.minusDays(6),date)),l28=load.total(workoutsBetween(all,date.minusDays(27),date));Double ratio=load.acuteChronicRatio(l7,l28);RecoveryEntity r=recovery.calculate(date,repo.getDailyHealth(date),repo.getBaseline("sleepMinutes",28),repo.getBaseline("restingHeartRate",28),ratio,repo.getCheckIn(date));repo.saveRecovery(r);}
 private static List<WorkoutEntity> workoutsForDay(List<WorkoutEntity> all,LocalDate day){return workoutsBetween(all,day,day);}private static List<WorkoutEntity> workoutsBetween(List<WorkoutEntity> all,LocalDate from,LocalDate to){ZoneId z=ZoneId.systemDefault();Instant start=from.atStartOfDay(z).toInstant(),end=to.plusDays(1).atStartOfDay(z).toInstant();List<WorkoutEntity> out=new ArrayList<>();for(WorkoutEntity w:all)if(w.startTime!=null&&!w.startTime.isBefore(start)&&w.startTime.isBefore(end))out.add(w);return out;}
}
